/**
 * 设置块的示例：「个人资料」。复制后改名，每个块一份文件。
 *
 * 块内照搬表单模板（ADR 0014）：一个 `useFormState` 单对象、`form-fields` 的字段、`SettingsSection` 承载。
 * 页脚只有保存，没有取消。成功时 `toast.success`，基线换成刚存下的值，保存按钮回到禁用；不关闭任何东西。
 * 脏态由 `SettingsSection` 经 `useSettingsDirty` 上报，离开拦截由 `SettingsLayout` 统一挂。
 */
import { useId } from "react";
import { toast } from "sonner";

import { FieldGroup } from "@/components/ui/field";
import { TextareaField, TextField, type Validators } from "@/components/ui/form-fields";
import { type SubmitResult, useFormState } from "../form-page/use-form-state";
import { SettingsSection } from "./settings-section";

export type ProfileValues = {
  displayName: string;
  email: string;
  bio: string;
};

/** 字段名，用于「为什么不能提交」。顺序即字段在页面上的顺序。 */
export const PROFILE_LABELS: Record<keyof ProfileValues, string> = {
  displayName: "显示名称",
  email: "邮箱",
  bio: "简介",
};

export const PROFILE_VALIDATORS: Validators<ProfileValues> = {
  displayName: (value) => {
    if (value.trim() === "") return "请填写显示名称";
    return value.trim().length > 30 ? "显示名称不能超过 30 个字符" : null;
  },
  email: (value) => (/^[^\s@]+@[^\s@]+$/.test(value) ? null : "请填写有效的邮箱"),
  bio: (value) => (value.length > 200 ? "简介不能超过 200 个字符" : null),
};

export function ProfileSection({
  initialValues,
  submit,
}: {
  /** 已存的值，通常来自分区路由的 loader。 */
  initialValues: ProfileValues;
  submit: (values: ProfileValues) => Promise<SubmitResult>;
}) {
  const id = useId();
  const form = useFormState({
    initialValues,
    validators: PROFILE_VALIDATORS,
    labels: PROFILE_LABELS,
    submit,
    onSaved: () => toast.success("已保存个人资料"),
  });
  const { values, onChange, errors } = form;
  const disabled = form.isPending;

  return (
    <SettingsSection title="个人资料" description="团队成员会看到这些信息。" form={form}>
      <FieldGroup>
        <TextField
          id={`${id}-display-name`}
          label={PROFILE_LABELS.displayName}
          required
          hint="最多 30 个字符"
          value={values.displayName}
          onValueChange={(displayName) => onChange({ ...values, displayName })}
          error={errors.displayName}
          disabled={disabled}
          autoComplete="nickname"
        />
        <TextField
          id={`${id}-email`}
          label={PROFILE_LABELS.email}
          required
          type="email"
          value={values.email}
          onValueChange={(email) => onChange({ ...values, email })}
          error={errors.email}
          disabled={disabled}
          autoComplete="email"
        />
        <TextareaField
          id={`${id}-bio`}
          label={PROFILE_LABELS.bio}
          hint="选填，最多 200 个字符"
          value={values.bio}
          onValueChange={(bio) => onChange({ ...values, bio })}
          error={errors.bio}
          disabled={disabled}
        />
      </FieldGroup>
    </SettingsSection>
  );
}

/**
 * 危险区（ADR 0018）：作用于整个账户或集成的危险动作（注销、删除、轮换密钥）。
 *
 * - 放在所属分区末尾，和上方内容之间用 `Separator` 隔开。不属于任何设置块，不进任何 `<form>`，不藏进下拉菜单。
 * - 卡片描边 `border-destructive`，标题 `text-destructive-subtle-foreground`。
 * - 每个动作一行（`DangerZoneItem`）：左边后果说明，末尾固定写「此操作不可撤销。」；右边 destructive 按钮，文字用明确的动词。
 * - 确认一律用 `ConfirmActionDialog`（打开时焦点在「取消」上）。不做「输入名称才能确认」。
 *   成功后要跳走时用 `useSettingsNavigateAway()`，这次跳转不被离开拦截挡住。
 */
import type { ReactNode } from "react";
import { useId } from "react";

import { Button } from "@/components/ui/button";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { Separator } from "@/components/ui/separator";

export function SettingsDangerZone({
  title = "危险操作",
  description,
  children,
}: {
  /** 标题（h2），缺省「危险操作」。 */
  title?: string;
  description?: ReactNode;
  /** 一个或多个 `DangerZoneItem`。`ConfirmActionDialog` 也可以放在这里。 */
  children: ReactNode;
}) {
  const titleId = useId();
  return (
    <div data-slot="settings-danger-zone" className="flex flex-col gap-6">
      <Separator />
      <section aria-labelledby={titleId}>
        <Card className="border border-destructive ring-0">
          <CardHeader>
            <CardTitle className="text-destructive-subtle-foreground">
              <h2 id={titleId}>{title}</h2>
            </CardTitle>
            {description ? <CardDescription>{description}</CardDescription> : null}
          </CardHeader>
          <CardContent className="@container flex flex-col divide-y divide-border">
            {children}
          </CardContent>
        </Card>
      </section>
    </div>
  );
}

export function DangerZoneItem({
  title,
  description,
  actionLabel,
  onAction,
  disabled = false,
  irreversibleNote = "此操作不可撤销。",
}: {
  /** 动作名，如「注销账户」。 */
  title: string;
  /** 后果说明，如「删除账户和全部数据。」。「此操作不可撤销。」由组件补在末尾，不要再写。 */
  description: ReactNode;
  /** 按钮文字，明确的动词，如「注销账户」。不写「确定」「提交」。 */
  actionLabel: string;
  /** 打开确认框，如 `() => actions.open("delete")`。不要在这里直接执行动作。 */
  onAction: () => void;
  disabled?: boolean;
  irreversibleNote?: string;
}) {
  return (
    <div className="flex flex-col gap-3 py-3 first:pt-0 last:pb-0 @md:flex-row @md:items-center @md:justify-between">
      <div className="flex min-w-0 flex-col gap-1">
        <p className="font-medium text-xs">{title}</p>
        <p className="text-muted-foreground text-xs">
          {description}
          {irreversibleNote}
        </p>
      </div>
      <Button
        variant="destructive"
        className="self-start @md:self-auto"
        disabled={disabled}
        onClick={onAction}
      >
        {actionLabel}
      </Button>
    </div>
  );
}

/**
 * 设置模板的布局（ADR 0018）。消费者的设置布局路由渲染 `<SettingsLayout>`，分区路由的内容作为 children。
 *
 * - 分区导航读 `sections` 数组，渲染成 `<nav aria-label>` 里的一列链接，当前项带 `aria-current="page"`。
 *   容器宽时在内容左侧，容器窄时变成内容上方一行可横向滚动的链接；按容器宽度切换，不按视口。只有一个分区时不渲染。
 * - 缺省分区由消费者的 index 路由重定向，本模板不做跳转。不用 `Tabs`，不用 search param。
 * - 离开拦截全页只挂一份：块用 `useSettingsDirty(dirty)` 上报，只要有一块脏就拦（表单模板的 `usePageLeaveGuard`）。
 *   适配对象没有 `useNavigationBlocker` 时按 ADR 0015 退化；这时分区导航的链接自己弹确认框，和整页表单的「取消」一样。
 * - `useSettingsNavigateAway()` 返回 `navigateAway(href)`：先置「跳过下一次拦截」的标记再跳转，危险动作成功后用它。
 * 不渲染 `<main>`：`<main>` 由 AppShell 渲染。链接都是宿主解析好的字符串（ADR 0005）。
 */
import {
  createContext,
  type MouseEvent,
  type ReactNode,
  use,
  useCallback,
  useEffect,
  useId,
  useState,
} from "react";

import { isNavItemActive, type NavMatch, useLinkAdapter } from "../app-shell/link-adapter";
import { leaveDecision } from "../form-page/page-leave";
import { usePageLeaveGuard } from "../form-page/page-leave-guard";
import { anyDirty, type DirtyBlocks, sectionNav, updateDirty } from "./settings-model";

/** 一个分区。`href`、`match` 与外壳导航项同形：`href` 是宿主解析好的字符串，`match` 缺省 `"exact"`。 */
export interface SettingsNavSection {
  id: string;
  label: string;
  href: string;
  match?: NavMatch;
  icon?: ReactNode;
}

type SettingsContextValue = {
  reportDirty: (id: string, dirty: boolean) => void;
  navigateAway: (href: string) => void;
};

const SettingsContext = createContext<SettingsContextValue | null>(null);

const EMPTY: DirtyBlocks = new Set();

/** 读布局 context。读不到时抛错：在 `SettingsLayout` 之外调用是硬依赖缺失（ADR 0009、ADR 0018）。 */
function useSettingsContext(hook: string): SettingsContextValue {
  const context = use(SettingsContext);
  if (context === null) {
    throw new Error(
      `${hook} 必须在 <SettingsLayout> 之内使用：设置布局路由渲染 <SettingsLayout>，分区路由的内容作为它的 children（ADR 0018）。`,
    );
  }
  return context;
}

/**
 * 设置块上报自己的脏态。块卸载时自动撤回。`SettingsSection` 传了 `form` 时已经替你调用；
 * 自己拼的块才要直接调用。
 */
export function useSettingsDirty(dirty: boolean): void {
  const { reportDirty } = useSettingsContext("useSettingsDirty");
  const id = useId();
  useEffect(() => {
    reportDirty(id, dirty);
  }, [reportDirty, id, dirty]);
  useEffect(() => () => reportDirty(id, false), [reportDirty, id]);
}

/** 返回 `navigateAway(href)`：先置「跳过下一次拦截」的标记再跳转。危险动作成功后跳走用它，不用 `navigate`。 */
export function useSettingsNavigateAway(): (href: string) => void {
  return useSettingsContext("useSettingsNavigateAway").navigateAway;
}

export type SettingsLayoutProps = {
  /** 页面标题（h1），如「设置」。 */
  title: string;
  description?: ReactNode;
  /** 分区，按显示顺序。按权限过滤在传入前做完（#17）。 */
  sections: readonly SettingsNavSection[];
  /** 分区导航的可访问名称，缺省「设置分区」。 */
  navLabel?: string;
  /** 当前分区的内容，即分区路由的 Outlet。 */
  children: ReactNode;
};

export function SettingsLayout({
  title,
  description,
  sections,
  navLabel = "设置分区",
  children,
}: SettingsLayoutProps) {
  const [dirtyBlocks, setDirtyBlocks] = useState<DirtyBlocks>(EMPTY);
  const dirty = anyDirty(dirtyBlocks);
  const { leave, navigateAway, guard } = usePageLeaveGuard(dirty);
  const reportDirty = useCallback((id: string, next: boolean) => {
    setDirtyBlocks((current) => updateDirty(current, id, next));
  }, []);
  const context: SettingsContextValue = { reportDirty, navigateAway };

  return (
    <div
      data-slot="settings-layout"
      className="mx-auto flex w-full max-w-5xl flex-1 flex-col gap-6 p-6"
    >
      <header className="flex flex-col gap-1">
        <h1 className="font-semibold text-lg">{title}</h1>
        {description ? <p className="text-muted-foreground text-xs">{description}</p> : null}
      </header>
      <div className="@container flex-1">
        <div className="flex flex-col gap-6 @3xl:flex-row @3xl:items-start">
          <SettingsSectionNav sections={sections} label={navLabel} dirty={dirty} leave={leave} />
          <SettingsContext value={context}>
            <div className="flex min-w-0 flex-1 flex-col gap-6">{children}</div>
          </SettingsContext>
        </div>
      </div>
      {guard}
    </div>
  );
}

const NAV_LINK =
  "flex h-8 items-center gap-2 whitespace-nowrap px-2 text-xs outline-none transition-colors focus-visible:ring-2 focus-visible:ring-ring/50";
const NAV_LINK_ACTIVE = `${NAV_LINK} bg-muted font-medium text-foreground`;
const NAV_LINK_IDLE = `${NAV_LINK} text-muted-foreground hover:bg-muted hover:text-foreground`;

function isPlainClick(event: MouseEvent<HTMLElement>): boolean {
  return event.button === 0 && !event.metaKey && !event.ctrlKey && !event.shiftKey && !event.altKey;
}

function SettingsSectionNav({
  sections,
  label,
  dirty,
  leave,
}: {
  sections: readonly SettingsNavSection[];
  label: string;
  dirty: boolean;
  leave: (href: string) => void;
}) {
  const { Link, pathname, useNavigationBlocker } = useLinkAdapter();
  const nav = sectionNav(sections, (section) => isNavItemActive(section, pathname));
  if (!nav.visible) return null;

  // 退化路径（ADR 0015）：适配对象拦不住站内跳转时，分区链接在捕获阶段先截下点击，由 leave 弹确认框。
  const onClickCapture = (event: MouseEvent<HTMLElement>) => {
    if (leaveDecision(dirty, useNavigationBlocker !== undefined) !== "confirm") return;
    if (!isPlainClick(event)) return;
    const anchor = (event.target as HTMLElement).closest("a");
    const href = anchor?.getAttribute("href");
    if (!href) return;
    event.preventDefault();
    event.stopPropagation();
    leave(href);
  };

  return (
    <nav aria-label={label} onClickCapture={onClickCapture} className="@3xl:w-48 @3xl:shrink-0">
      <ul className="flex gap-1 overflow-x-auto @3xl:flex-col @3xl:overflow-visible">
        {sections.map((section) => {
          const active = section.id === nav.activeId;
          return (
            <li key={section.id} className="shrink-0">
              <Link
                href={section.href}
                aria-current={active ? "page" : undefined}
                className={active ? NAV_LINK_ACTIVE : NAV_LINK_IDLE}
              >
                {section.icon ? (
                  <span aria-hidden className="flex size-4 items-center *:size-4">
                    {section.icon}
                  </span>
                ) : null}
                {section.label}
              </Link>
            </li>
          );
        })}
      </ul>
    </nav>
  );
}

/**
 * 设置模板的纯逻辑（ADR 0018）：块的脏态汇总、分区导航的当前项与是否渲染。
 * 不 import React，也不 import 任何路由库。
 */

/** 脏的块的 id 集合。 */
export type DirtyBlocks = ReadonlySet<string>;

/**
 * 块上报脏态（`useSettingsDirty`）后的新集合。块卸载时上报 `false`。
 * 状态不变时返回原集合，调用方的 setState 因此不会多渲染一次。不改动传入的集合。
 */
export function updateDirty(blocks: DirtyBlocks, id: string, dirty: boolean): DirtyBlocks {
  if (blocks.has(id) === dirty) return blocks;
  const next = new Set(blocks);
  if (dirty) next.add(id);
  else next.delete(id);
  return next;
}

/** 只要有一块脏，布局就挂离开拦截。 */
export function anyDirty(blocks: DirtyBlocks): boolean {
  return blocks.size > 0;
}

/**
 * 分区导航的状态。`isActive` 由调用方传入外壳的 `isNavItemActive`（按 `match` 计算，缺省 `"exact"`）。
 * - `visible`：两个以上分区才渲染导航，只有一个分区时不渲染。
 * - `activeId`：第一个命中的分区；都不命中时为 null。
 */
export function sectionNav<TSection extends { id: string }>(
  sections: readonly TSection[],
  isActive: (section: TSection) => boolean,
): { visible: boolean; activeId: string | null } {
  return {
    visible: sections.length > 1,
    activeId: sections.find(isActive)?.id ?? null,
  };
}

/**
 * 设置块（ADR 0018）：一张卡片，对应一个 `<form>`、一个保存按钮。它就是保存单位：没有「保存全部」，也不改完就自动保存。
 *
 * - 传 `form`（`useFormState` 的返回值）：`<form>` 包住 `Card`，页脚只有保存，没有取消。
 *   保存按钮在块未改动或保存中时禁用，保存中显示「保存中…」；失败用 `FormError` 显示在页脚上方。
 *   块的脏态自动经 `useSettingsDirty` 上报给 `SettingsLayout`，所以必须放在 `SettingsLayout` 之内。
 * - 不传 `form`：只读块，没有页脚。放 `DescriptionList` 这类不可编辑的事实。
 * - `SettingsSectionSkeleton`、`SettingsSectionError`：块（或整个分区）的加载中与加载失败。
 * 成功时的 `toast.success` 写在 `useFormState` 的 `onSaved` 里，不关闭任何东西。
 */
import type { FormEvent, ReactNode, RefObject } from "react";
import { useId } from "react";

import { Button } from "@/components/ui/button";
import {
  Card,
  CardAction,
  CardContent,
  CardDescription,
  CardFooter,
  CardHeader,
  CardTitle,
} from "@/components/ui/card";
import { FormError } from "@/components/ui/form-error";
import { Skeleton } from "@/components/ui/skeleton";
import { useSettingsDirty } from "./settings-layout";

/** `SettingsSection` 用到的 `useFormState` 返回值的子集。直接把 `useFormState(…)` 的结果传进来。 */
export type SettingsSectionForm = {
  formRef: RefObject<HTMLFormElement | null>;
  handleSubmit: (event: FormEvent<HTMLFormElement>) => void;
  dirty: boolean;
  isPending: boolean;
  error: string | null;
  blockedReason: string | null;
};

type SettingsSectionBase = {
  /** 块标题（h2），如「个人资料」。 */
  title: string;
  description?: ReactNode;
  /** 卡片右上角的一个动作。 */
  action?: ReactNode;
  children: ReactNode;
};

export type SettingsSectionProps = SettingsSectionBase &
  (
    | {
        form: SettingsSectionForm;
        /** 保存按钮文案，缺省「保存」。 */
        saveLabel?: string;
        /** 保存中的文案，缺省「保存中…」（U+2026）。 */
        pendingLabel?: string;
      }
    | { form?: undefined; saveLabel?: never; pendingLabel?: never }
  );

function SectionHeader({
  titleId,
  title,
  description,
  action,
}: Omit<SettingsSectionBase, "children"> & { titleId: string }) {
  return (
    <CardHeader>
      <CardTitle>
        <h2 id={titleId}>{title}</h2>
      </CardTitle>
      {description ? <CardDescription>{description}</CardDescription> : null}
      {action ? <CardAction>{action}</CardAction> : null}
    </CardHeader>
  );
}

export function SettingsSection(props: SettingsSectionProps) {
  if (props.form !== undefined) return <SettingsFormSection {...props} form={props.form} />;
  return <SettingsReadOnlySection {...props} />;
}

function SettingsReadOnlySection({ title, description, action, children }: SettingsSectionBase) {
  const titleId = useId();
  return (
    <section aria-labelledby={titleId}>
      <Card>
        <SectionHeader titleId={titleId} title={title} description={description} action={action} />
        <CardContent>{children}</CardContent>
      </Card>
    </section>
  );
}

function SettingsFormSection({
  title,
  description,
  action,
  children,
  form,
  saveLabel = "保存",
  pendingLabel = "保存中…",
}: SettingsSectionBase & { form: SettingsSectionForm; saveLabel?: string; pendingLabel?: string }) {
  useSettingsDirty(form.dirty);
  const id = useId();
  const titleId = `${id}-title`;
  const saveLabelId = `${id}-save-label`;
  const blockedId = `${id}-blocked`;
  return (
    <form ref={form.formRef} onSubmit={form.handleSubmit} noValidate aria-labelledby={titleId}>
      <Card>
        <SectionHeader titleId={titleId} title={title} description={description} action={action} />
        <CardContent className="flex flex-col gap-6">
          {children}
          <FormError message={form.error} />
        </CardContent>
        <CardFooter className="flex-wrap justify-end gap-2">
          <p
            id={blockedId}
            hidden={form.blockedReason === null}
            className="mr-auto text-destructive-subtle-foreground text-xs"
          >
            {form.blockedReason}
          </p>
          <Button
            type="submit"
            disabled={!form.dirty || form.isPending}
            focusableWhenDisabled
            aria-labelledby={saveLabelId}
            aria-describedby={blockedId}
          >
            <span id={saveLabelId}>{form.isPending ? pendingLabel : saveLabel}</span>
          </Button>
        </CardFooter>
      </Card>
    </form>
  );
}

const SKELETON_KEYS = ["a", "b", "c", "d", "e", "f"];

/**
 * 块的加载中：卡片形状的骨架。分区路由的 pending 按块数各放一个；只读块写 `footer={false}`。
 * 标题只给读屏软件。
 */
export function SettingsSectionSkeleton({
  fields = 2,
  footer = true,
  label = "加载中…",
}: {
  /** 字段行数，缺省 2，最多 6。 */
  fields?: number;
  /** 有保存页脚的块为真（缺省）。 */
  footer?: boolean;
  label?: string;
}) {
  return (
    <Card data-slot="settings-section-skeleton" aria-busy="true">
      <span className="sr-only">{label}</span>
      <CardHeader>
        <Skeleton className="h-4 w-32" />
        <Skeleton className="h-3 w-56 max-w-full" />
      </CardHeader>
      <CardContent className="flex flex-col gap-4">
        {SKELETON_KEYS.slice(0, fields).map((key) => (
          <div key={key} className="flex flex-col gap-2">
            <Skeleton className="h-3 w-20" />
            <Skeleton className="h-8 w-full" />
          </div>
        ))}
      </CardContent>
      {footer ? (
        <CardFooter className="justify-end">
          <Skeleton className="h-8 w-14" />
        </CardFooter>
      ) : null}
    </Card>
  );
}

/** 块（或整个分区）的数据没能加载出来。保存失败不用它，用块里的 `FormError`。 */
export function SettingsSectionError({
  title,
  description = "这一块设置没能加载出来，请稍后重试。",
  onRetry,
  retryLabel = "重试",
}: {
  /** 块标题，让用户知道是哪一块没加载出来。 */
  title: string;
  description?: ReactNode;
  /** 重试，如重新取数或 `router.invalidate()`。不传就不显示重试按钮。 */
  onRetry?: () => void;
  retryLabel?: string;
}) {
  const titleId = useId();
  return (
    <section aria-labelledby={titleId} data-slot="settings-section-error">
      <Card>
        <CardHeader>
          <CardTitle>
            <h2 id={titleId}>{title}</h2>
          </CardTitle>
          <CardDescription className="text-destructive-subtle-foreground">
            {description}
          </CardDescription>
          {onRetry ? (
            <CardAction>
              <Button variant="outline" size="sm" onClick={onRetry}>
                {retryLabel}
              </Button>
            </CardAction>
          ) : null}
        </CardHeader>
      </Card>
    </section>
  );
}
